CREATE TABLE readings(station INT NOT NULL LATENESS 2, t INT NOT NULL LATENESS 1);
CREATE TABLE forecasts(station INT NOT NULL LATENESS 4, t INT NOT NULL LATENESS 3);
CREATE VIEW paired AS SELECT r.station, r.t AS observed, f.t AS expected
FROM readings AS r JOIN forecasts AS f ON r.station = f.station;
CREATE VIEW projected AS SELECT station, observed + expected AS total FROM paired;
